/* Real paper textures — window.StudioPapers.
   Scans and photos of real paper, turned into multiply maps (the sheet itself is white, its fibres, folds, foxing and
   stains stay): laid over the background colour they read as that paper. Sources are free to bundle: ambientCG (CC0)
   and Wikimedia Commons (public domain / CC0); see `credit`. Made with tools/papers_prep.py. */
(function () {
  'use strict';
  const LIST = [
    { id: 'natural', name: 'Natural', kind: 'clean', credit: "Fibre of ambientCG Paper001 (CC0) with the mottle of “Old paper6”, Wikimedia Commons (public domain)", src: 'data:image/jpeg;base64,' },
    { id: 'cotton', name: 'Cotton', kind: 'clean', credit: "ambientCG Paper001 — https://ambientcg.com/a/Paper001 (CC0)", src: 'data:image/jpeg;base64,' },
    { id: 'vellum', name: 'Vellum', kind: 'clean', credit: "“Pergament.2.jpg”, Wikimedia Commons (CC0) — https://commons.wikimedia.org/wiki/File:Pergament.2.jpg", src: 'data:image/jpeg;base64,' },
    { id: 'creased', name: 'Creased', kind: 'clean', credit: "ambientCG Paper003 — https://ambientcg.com/a/Paper003 (CC0)", src: 'data:image/jpeg;base64,' },
    { id: 'recycled', name: 'Recycled', kind: 'clean', credit: "ambientCG Paper002 — https://ambientcg.com/a/Paper002 (CC0)", src: 'data:image/jpeg;base64,' },
    { id: 'kraft', name: 'Kraft', kind: 'clean', credit: "ambientCG Paper006 — https://ambientcg.com/a/Paper006 (CC0)", src: 'data:image/jpeg;base64,' },
    { id: 'laid', name: 'Laid', kind: 'clean', credit: "ambientCG Paper004 — https://ambientcg.com/a/Paper004 (CC0)", src: 'data:image/jpeg;base64,' },
    { id: 'aged', name: 'Aged', kind: 'aged', credit: "“Old paper1.jpg”, Wikimedia Commons (public domain) — https://commons.wikimedia.org/wiki/File:Old_paper1.jpg", src: 'data:image/jpeg;base64,' },
    { id: 'parchment', name: 'Parchment', kind: 'aged', credit: "“Old paper6.jpg”, Wikimedia Commons (public domain) — https://commons.wikimedia.org/wiki/File:Old_paper6.jpg", src: 'data:image/jpeg;base64,' },
    { id: 'folded', name: 'Folded letter', kind: 'aged', credit: "“Old paper7.jpg”, Wikimedia Commons (public domain) — https://commons.wikimedia.org/wiki/File:Old_paper7.jpg", src: 'data:image/jpeg;base64,' },
    { id: 'stained', name: 'Water-stained', kind: 'aged', credit: "“Old paper2.jpg”, Wikimedia Commons (public domain) — https://commons.wikimedia.org/wiki/File:Old_paper2.jpg", src: 'data:image/jpeg;base64,' },
    { id: 'burnt', name: 'Burnt edges', kind: 'aged', credit: "“Old Paper texture.jpg”, Wikimedia Commons (public domain) — https://commons.wikimedia.org/wiki/File:Old_Paper_texture.jpg", src: 'data:image/jpeg;base64,' },
  ];
  const BY = {}; for (const p of LIST) BY[p.id] = p;
  window.StudioPapers = { LIST, byId: id => BY[id], DEFAULT: 'natural' };
})();
